const renderRich = (text: string): React.ReactNode => {
  const parts = String(text).split(/\*\*(.+?)\*\*/g)
  return parts.map((part, index) =>
    index % 2 === 1 ? <strong key={index}>{part}</strong> : part
  )
}

const StackBadges = ({ stacks }: { stacks: string[] }) => (
  <div className="portfolio-stack-badges">
    {stacks.map(name => {
      const style = STACK_BADGE_STYLES[name] ?? {
        backgroundColor: "#374151",
      }
      return <StackBadge name={name} {...style} key={name} />
    })}
  </div>
)

const Narrative = ({ sections }: { sections: NarrativeSection[] }) => (
  <ul className="portfolio-narrative">
    {sections.flatMap(section => {
      const paragraphs = Array.isArray(section.body)
        ? section.body
        : [section.body]

      return paragraphs.map(paragraph => (
        <li key={paragraph}>{renderRich(paragraph)}</li>
      ))
    })}
  </ul>
)

const ContentParagraphs = ({ items }: { items: string[] }) => (
  <>
    {items.map((item, index) => (
      <p key={index}>{renderRich(item)}</p>
    ))}
  </>
)

